	for _, want := range []string{"swarm serve · ", "store                      sqlite · " + sqlitePath, "workspace                  host · agent work runs on this machine", "listeners                  api 127.0.0.1:", "ready in ", "telegram webhook", "webhook_signing.telegram bound", "shutdown · complete"} {
