		if err := credentialStore.Set(context.Background(), key, value); err != nil {
			t.Fatalf("set live graduation credential %s: %v", key, err)
		}
	}
	prepared, err := store.NewSQLiteRuntimeStore(sqlitePath)
	if err != nil {
		t.Fatal(err)
	}
	preparedClosed := false
	t.Cleanup(func() {
		if !preparedClosed {
			if err := prepared.Close(); err != nil {
				t.Error(err)
			}
		}
	})
	bundle := loadWorkflowValidationBundleAt(t, sourceRoot)
	plans, err := cliapp.StateStoreSchemaPlans(bundle)
	if err != nil {
		t.Fatal(err)
	}
	schema, err := cliapp.SchemaBootstrapRequest(bundle.Platform, plans.Platform, plans.State)
	if err != nil {
		t.Fatal(err)
	}
	if err := prepared.BootstrapSchema(context.Background(), schema); err != nil {
		t.Fatal(err)
	}
	capability, err := prepared.AcquireProcessCapability(context.Background(), startupownership.AcquireRequest{OwnerID: "live-channel-verification-fixture", BootID: uuid.NewString(), RuntimeInstanceID: uuid.NewString()})
	if err != nil {
		t.Fatal(err)
	}
	if err := capability.Release(context.Background()); err != nil {
		t.Fatal(err)
	}
	if err := prepared.Close(); err != nil {
		t.Fatal(err)
	}
	preparedClosed = true
	var verifyOut, verifyErr bytes.Buffer
	if code := executeCLIFrom(context.Background(), sourceRoot, []string{"verify", sourceRoot, "--config", configPath, "--json"}, &verifyOut, &verifyErr, Run); code != 0 {
		t.Fatalf("explicit live graduation verify exit=%d\nstdout:\n%s\nstderr:\n%s", code, verifyOut.String(), verifyErr.String())
	}
	var admission struct {
		OK                bool   `json:"ok"`
		AdmissionComplete bool   `json:"admission_complete"`
		ValidationScope   string `json:"validation_scope"`
		LiveReadiness     string `json:"live_readiness"`
	}
	if err := json.Unmarshal(verifyOut.Bytes(), &admission); err != nil {
		t.Fatal(err)
	}
	if !admission.OK || !admission.AdmissionComplete || admission.ValidationScope != "deployment" || admission.LiveReadiness != "not_evaluated" {
		t.Fatalf("live graduation did not complete admission without claiming execution: %s", &verifyOut)
	}
	providerRecorder := &standingLiveAnthropicRecorder{t: t}
	provider := httptest.NewServer(providerRecorder)
	t.Cleanup(provider.Close)
	telegramCalls := make(chan map[string]any, 4)
	telegram := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, req *http.Request) {
		if req.URL.Path != "/botbot-token/sendMessage" {
			t.Errorf("Telegram path = %q, want credential-bearing bot route", req.URL.Path)
			http.Error(w, "unexpected path", http.StatusNotFound)
			return
		}
		var body map[string]any
		if err := json.NewDecoder(req.Body).Decode(&body); err != nil {
			t.Errorf("decode Telegram live request: %v", err)
			http.Error(w, "bad request", http.StatusBadRequest)
			return
		}
		select {
		case telegramCalls <- body:
		default:
			t.Errorf("unexpected excess Telegram call: %#v", body)
			http.Error(w, "unexpected excess call", http.StatusConflict)
			return
		}
		w.Header().Set("content-type", "application/json")
		_, _ = w.Write([]byte(`{"ok":true,"result":{"message_id":1}}`))
	}))
	t.Cleanup(telegram.Close)
	redirectExternalHosts(t, map[string]string{"api.anthropic.com": provider.URL, "api.telegram.org": telegram.URL})
	opts := cliapp.ServeOptions{ConfigPath: configPath, SourceRoot: sourceRoot, PlatformSpecPath: filepath.Join(repoRootForTest(), defaultPlatformSpecPath), APIListenAddr: "127.0.0.1:0", MCPListenAddr: "127.0.0.1:0", SelfCheck: true, Dev: true, LocalRun: true, Verbose: true, TestOutboxSweeperConfig: servedEventPublishProofOutboxSweeperConfig()}
	process := startTelegramAgentServeRuntimeTestProcess(t, sourceRoot, opts)
	process.waitForReadyLine()
	baseURL := "http://" + serveRuntimeAPIListenerFromOutput(t, process.outputString())
	diagnostics := func() string {
		return process.outputString() + "\ndiagnostics: " + standingSQLiteDiagnostics(sqlitePath)
	}
	binding := sendStandingTelegramUpdate(t, baseURL, 201, 42, diagnostics)
	providerRecorder.waitForInitialCount(t, 1)
	waitForStandingMemoryCompletion(t, "sqlite", sqlitePath, "live", 1)
	requireStandingLiveTelegramCalls(t, telegramCalls, "Live turn 1: hello 201")
	if got := sendStandingTelegramUpdate(t, baseURL, 202, 42, diagnostics); got != binding {
		t.Fatalf("live graduation second binding = %+v, want same generation %+v", got, binding)
	}
	providerRecorder.waitForInitialCount(t, 2)
	waitForStandingMemoryCompletion(t, "sqlite", sqlitePath, "live", 2)
	requireStandingLiveTelegramCalls(t, telegramCalls, "Live turn 2: hello 202")
	requireStandingPayloadOnlyTargetReadback(t, baseURL, bundleHash, "live", 1, []string{"Live turn 1: hello 201", "Live turn 2: hello 202"})
	if code := process.stop(); code != 0 {
		t.Fatalf("live graduation serve exit = %d\n%s", code, process.outputString())
	}
	sessions := loadStandingMemorySessions(t, "sqlite", sqlitePath)
	if len(sessions) != 1 {
		t.Fatalf("live graduation memory sessions = %#v, want one conversation owner", sessions)
	}
	for _, session := range sessions {
		if session.AgentID != "phrase-bot" || session.FlowTemplate != "telegram-chat" || session.TurnCount != 2 {
			t.Fatalf("live graduation memory session = %#v, want phrase-bot telegram-chat with two turns", session)
		}
	}
}

