func standingStoreDiagnostics(backend, location string) string {
	owner, err := storetest.OpenReleaseProcessReadOnlyInspection(backend, location)
	if err != nil {
		return err.Error()
	}
	defer owner.Close()
	return renderStandingStoreDiagnostics(context.Background(), owner)
}

func renderStandingStoreDiagnostics(ctx context.Context, owner storetest.ReleaseProcessReadOnlyInspection) string {
	var names []storetest.StandingEventNameDiagnostic
	err := owner.InspectSnapshot(ctx, func(scoped context.Context) error {
		var err error
		names, err = storetest.ReadStandingEventNameDiagnostics(scoped, owner)
		return err
	})
	if err != nil {
		return err.Error()
	}
	parts := []string{}
	for _, row := range names {
		parts = append(parts, fmt.Sprintf("%s=%d", row.Name, row.Count))
	}
	var logs []string
	if err := owner.InspectSnapshot(ctx, func(scoped context.Context) error {
		var err error
		logs, err = storetest.ReadStandingRuntimeLogDiagnostics(scoped, owner)
		return err
	}); err == nil {
		parts = append(parts, logs...)
	}
	var deliveries []storetest.StandingDeliveryDiagnostic
	if err := owner.InspectSnapshot(ctx, func(scoped context.Context) error {
		var err error
		deliveries, err = storetest.ReadStandingDeliveryDiagnostics(scoped, owner)
		return err
	}); err == nil {
		for _, row := range deliveries {
			parts = append(parts, fmt.Sprintf("delivery:%s:%s:%s", row.EventID, row.Subscriber, row.Status))
		}
	}
	return strings.Join(parts, ",")
}

func ReadStandingEventNameDiagnosticsTx(ctx context.Context, tx *sql.Tx, postgres bool) ([]StandingEventNameDiagnostic, error) {
	rows, err := tx.QueryContext(ctx, `SELECT event_name, COUNT(*) FROM events GROUP BY event_name ORDER BY event_name`)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var out []StandingEventNameDiagnostic
	for rows.Next() {
		var row StandingEventNameDiagnostic
		if err := rows.Scan(&row.Name, &row.Count); err != nil {
			if !postgres {
				return nil, errors.Join(err, rows.Close())
			}
			continue
		}
		out = append(out, row)
	}
	if err := errors.Join(rows.Err(), rows.Close()); err != nil {
		return nil, err
	}
	return out, nil
}

func ReadStandingRuntimeLogDiagnosticsTx(ctx context.Context, tx *sql.Tx, postgres bool) ([]string, error) {
	query := `SELECT payload FROM events WHERE event_name = 'platform.runtime_log' ORDER BY created_at`
	if postgres {
		query = `SELECT payload::text FROM events WHERE event_name = 'platform.runtime_log' ORDER BY created_at`
	}
	rows, err := tx.QueryContext(ctx, query)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var out []string
	for rows.Next() {
		var payload string
		if rows.Scan(&payload) == nil {
			out = append(out, payload)
		}
	}
	if err := errors.Join(rows.Err(), rows.Close()); err != nil {
		return nil, err
	}
	return out, nil
}

func ReadStandingDeliveryDiagnosticsTx(ctx context.Context, tx *sql.Tx, postgres bool) ([]StandingDeliveryDiagnostic, error) {
	query := `SELECT event_id, subscriber_id, COALESCE(status, '') FROM event_deliveries ORDER BY created_at`
	if postgres {
		query = `SELECT event_id::text, subscriber_id, COALESCE(status, '') FROM event_deliveries ORDER BY created_at`
	}
	rows, err := tx.QueryContext(ctx, query)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var out []StandingDeliveryDiagnostic
	for rows.Next() {
		var row StandingDeliveryDiagnostic
		if rows.Scan(&row.EventID, &row.Subscriber, &row.Status) == nil {
			out = append(out, row)
		}
	}
	if err := errors.Join(rows.Err(), rows.Close()); err != nil {
		return nil, err
	}
	return out, nil
}

